var authGuard = (route, state2) => {
  const authService = inject(AuthService);
  const router = inject(Router);
  if (authService.isLoggedIn()) {
    return true;
  }
  return router.createUrlTree(["/login"], { queryParams: { returnUrl: state2.url } });
};

